// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title ERC1967Utils
/// @notice Storage slot helpers for ERC-1967 proxy patterns
/// @dev Defines standard storage slots for implementation, admin, and beacon addresses
library ERC1967Utils {
    /// @dev bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1)
    bytes32 internal constant IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /// @dev bytes32(uint256(keccak256("eip1967.proxy.beacon")) - 1)
    bytes32 internal constant BEACON_SLOT =
        0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;

    /// @dev bytes32(uint256(keccak256("eip1967.proxy.admin")) - 1)
    bytes32 internal constant ADMIN_SLOT =
        0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    error InvalidImplementation();
    error InvalidBeacon();

    event Upgraded(address indexed implementation);
    event BeaconUpgraded(address indexed beacon);
    event AdminChanged(address previousAdmin, address newAdmin);

    /// @notice Returns the current implementation address
    function getImplementation() internal view returns (address impl) {
        assembly {
            impl := sload(IMPLEMENTATION_SLOT)
        }
    }

    /// @notice Sets the implementation address
    function setImplementation(address newImplementation) internal {
        if (newImplementation.code.length == 0) revert InvalidImplementation();
        assembly {
            sstore(IMPLEMENTATION_SLOT, newImplementation)
        }
        emit Upgraded(newImplementation);
    }

    /// @notice Returns the current beacon address
    function getBeacon() internal view returns (address beacon) {
        assembly {
            beacon := sload(BEACON_SLOT)
        }
    }

    /// @notice Sets the beacon address
    function setBeacon(address newBeacon) internal {
        if (newBeacon.code.length == 0) revert InvalidBeacon();
        assembly {
            sstore(BEACON_SLOT, newBeacon)
        }
        emit BeaconUpgraded(newBeacon);
    }

    /// @notice Returns the current admin address
    function getAdmin() internal view returns (address admin) {
        assembly {
            admin := sload(ADMIN_SLOT)
        }
    }

    /// @notice Sets the admin address
    function setAdmin(address newAdmin) internal {
        address previous = getAdmin();
        assembly {
            sstore(ADMIN_SLOT, newAdmin)
        }
        emit AdminChanged(previous, newAdmin);
    }
}

contracts/base/Initializable.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title Initializable
/// @notice Initialization guard for proxied contracts. Replaces constructors.
/// @dev Supports versioned reinitializers and disableInitializers for implementations.
abstract contract Initializable {
    /// @dev Storage slot for initialization state (avoids storage collision in proxies)
    /// keccak256("sidiora.initializable.storage") - 1
    bytes32 private constant _INITIALIZABLE_STORAGE =
        0x4377386e2795aba8c0ce23a1e6e67bac790e4b4166f14b7e9365049ab946f8c0;

    struct InitializableStorage {
        uint64 initialized;
        bool initializing;
    }

    error AlreadyInitialized();
    error NotInitializing();

    event Initialized(uint64 version);

    modifier initializer() {
        InitializableStorage storage $ = _getInitializableStorage();
        bool isTopLevel = !$.initializing;

        uint64 initialized = $.initialized;
        if (initialized >= 1 && isTopLevel) revert AlreadyInitialized();
        if (initialized != 0 && !isTopLevel) revert AlreadyInitialized();

        if (isTopLevel) {
            $.initializing = true;
        }
        $.initialized = 1;
        _;
        if (isTopLevel) {
            $.initializing = false;
            emit Initialized(1);
        }
    }

    modifier reinitializer(uint64 version) {
        InitializableStorage storage $ = _getInitializableStorage();
        if ($.initializing || $.initialized >= version) revert AlreadyInitialized();
        $.initialized = version;
        $.initializing = true;
        _;
        $.initializing = false;
        emit Initialized(version);
    }

    modifier onlyInitializing() {
        if (!_isInitializing()) revert NotInitializing();
        _;
    }

    /// @notice Locks the contract, preventing any future initialization
    /// @dev Call in the constructor of implementation contracts
    function _disableInitializers() internal virtual {
        InitializableStorage storage $ = _getInitializableStorage();
        if ($.initializing) revert AlreadyInitialized();
        if ($.initialized != type(uint64).max) {
            $.initialized = type(uint64).max;
            emit Initialized(type(uint64).max);
        }
    }

    function _getInitializedVersion() internal view returns (uint64) {
        return _getInitializableStorage().initialized;
    }

    function _isInitializing() internal view returns (bool) {
        return _getInitializableStorage().initializing;
    }

    function _getInitializableStorage() private pure returns (InitializableStorage storage $) {
        assembly {
            $.slot := _INITIALIZABLE_STORAGE
        }
    }
}

