// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title ReentrancyGuard
/// @notice Prevents reentrant calls to protected functions
/// @dev Uses a storage slot flag to detect and block reentrancy
abstract contract ReentrancyGuard {
    /// @dev keccak256("sidiora.reentrancyguard.storage") - 1
    bytes32 private constant _REENTRANCY_SLOT =
        0x9b779b17422d0df92223018b32b4d1fa46e071723d6817e2486d003becc55f00;

    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    error ReentrancyGuardReentrantCall();

    constructor() {
        _setStatus(_NOT_ENTERED);
    }

    modifier nonReentrant() {
        _nonReentrantBefore();
        _;
        _nonReentrantAfter();
    }

    function _nonReentrantBefore() private {
        if (_getStatus() == _ENTERED) revert ReentrancyGuardReentrantCall();
        _setStatus(_ENTERED);
    }

    function _nonReentrantAfter() private {
        _setStatus(_NOT_ENTERED);
    }

    function _getStatus() private view returns (uint256 status) {
        bytes32 slot = _REENTRANCY_SLOT;
        assembly {
            status := sload(slot)
        }
    }

    function _setStatus(uint256 status) private {
        bytes32 slot = _REENTRANCY_SLOT;
        assembly {
            sstore(slot, status)
        }
    }

    /// @dev Initialize reentrancy guard for proxied contracts (no constructor)
    function _initReentrancyGuard() internal {
        _setStatus(_NOT_ENTERED);
    }
}

contracts/base/UUPSUpgradeable.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "./ERC1967Utils.sol";
import "./Initializable.sol";

/// @title UUPSUpgradeable
/// @notice UUPS (Universal Upgradeable Proxy Standard) upgrade logic
/// @dev Implementation contracts inherit this. Proxy delegates to implementation.
///      Authorization for upgrades is defined by subclasses via _authorizeUpgrade.
abstract contract UUPSUpgradeable is Initializable {
    /// @dev keccak256("sidiora.uups.storage") - 1
    bytes32 private constant _UUPS_STORAGE =
        0x8b73c3c69bb8fe3d512ecc4cf759cc79239f7b179b0ffacaa9a75d522b39400f;

    error UnauthorizedUpgrade();
    error UUPSNotThroughProxy();
    error UUPSNotThroughActiveProxy();
    error InvalidImplementation();
    error NonPayableUpgrade();
    error UpgradeInitializationFailed();

    /// @dev Address of this implementation (set at deployment)
    address private immutable __self = address(this);

    /// @notice Checks that the function is called through a proxy
    modifier onlyProxy() {
        if (address(this) == __self) revert UUPSNotThroughProxy();
        if (ERC1967Utils.getImplementation() != __self) revert UUPSNotThroughActiveProxy();
        _;
    }

    /// @notice Checks that the function is NOT called through a proxy
    modifier notDelegated() {
        if (address(this) != __self) revert UUPSNotThroughActiveProxy();
        _;
    }

    /// @notice Returns the ERC-1822 proxiable UUID
    /// @dev Must return the ERC-1967 implementation slot to be compatible
    function proxiableUUID() external view notDelegated returns (bytes32) {
        return ERC1967Utils.IMPLEMENTATION_SLOT;
    }

    /// @notice Upgrades the implementation to a new address
    /// @param newImplementation The address of the new implementation
    /// @param data Optional calldata for initialization after upgrade
    function upgradeToAndCall(
        address newImplementation,
        bytes memory data
    ) external payable virtual onlyProxy {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallUUPS(newImplementation, data);
    }

    /// @notice Override this to define who can authorize upgrades
    function _authorizeUpgrade(address newImplementation) internal virtual;

    /// @dev Performs the upgrade, verifying the new implementation is UUPS-compatible
    function _upgradeToAndCallUUPS(
        address newImplementation,
        bytes memory data
    ) internal {
        if (data.length == 0 && msg.value != 0) revert NonPayableUpgrade();
        // Verify the new implementation is a valid UUPS contract
        try UUPSUpgradeable(newImplementation).proxiableUUID() returns (bytes32 slot) {
            if (slot != ERC1967Utils.IMPLEMENTATION_SLOT) {
                revert InvalidImplementation();
            }
        } catch {
            revert InvalidImplementation();
        }

        ERC1967Utils.setImplementation(newImplementation);

        if (data.length > 0) {
            (bool success, bytes memory reason) = newImplementation.delegatecall(data);
            if (!success) {
                if (reason.length == 0) revert UpgradeInitializationFailed();
                assembly { revert(add(reason, 32), mload(reason)) }
            }
        }
    }
}

contracts/libraries/SidioraMath.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title SidioraMath
/// @notice Core math primitives: sqrt, mulDiv, min, max, abs, safe casting
/// @dev All functions are pure/internal. No external dependencies.
library SidioraMath {
    error Overflow();
    error DivisionByZero();

    /// @notice Calculates floor(sqrt(x)) using the Babylonian method
    /// @param x The value to take the square root of
    /// @return z The floor of the square root
    function sqrt(uint256 x) internal pure returns (uint256 z) {
        if (x == 0) return 0;
        if (x <= 3) return 1;

        z = x;
        uint256 y = (x >> 1) + 1;
        while (y < z) {
            z = y;
            y = (x / y + y) >> 1;
        }
    }

    /// @notice Calculates (a * b) / denominator with 512-bit intermediate precision
    /// @dev Reverts on denominator == 0 or result overflow
    /// @param a Multiplicand
    /// @param b Multiplier
    /// @param denominator Divisor
    /// @return result The 256-bit result
    function mulDiv(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        if (denominator == 0) revert DivisionByZero();

        uint256 prod0;
        uint256 prod1;
        assembly {
            let mm := mulmod(a, b, not(0))
            prod0 := mul(a, b)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }

        if (prod1 == 0) {
            return prod0 / denominator;
        }

        if (prod1 >= denominator) revert Overflow();

        unchecked {
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, denominator)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = denominator & (0 - denominator);
            assembly {
                denominator := div(denominator, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;

            uint256 inverse = (3 * denominator) ^ 2;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;

            result = prod0 * inverse;
        }
    }

    /// @notice Calculates (a * b) / denominator, rounded up
    function mulDivRoundingUp(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        result = mulDiv(a, b, denominator);
        if (mulmod(a, b, denominator) > 0) {
            if (result == type(uint256).max) revert Overflow();
            result++;
        }
    }

    /// @notice Returns the smaller of two values
    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }

    /// @notice Returns the larger of two values
    function max(uint256 a, uint256 b) internal pure returns (uint256) {
        return a > b ? a : b;
    }

    /// @notice Returns the absolute value of a signed integer
    function abs(int256 x) internal pure returns (uint256) {
        return x >= 0 ? uint256(x) : uint256(-(x + 1)) + 1;
    }

    /// @notice Safely casts a uint256 to uint128
    function safeCastToUint128(uint256 x) internal pure returns (uint128) {
        if (x > type(uint128).max) revert Overflow();
        return uint128(x);
    }

    /// @notice Safely casts a uint256 to int256
    function safeCastToInt256(uint256 x) internal pure returns (int256) {
        if (x > uint256(type(int256).max)) revert Overflow();
        return int256(x);
    }
}

