// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

/**
 * @title IPECOROrders
 * @notice Interface for the PECOROrders engine — limit / stop-loss / stop-limit orders with
 *         keeper execution against PECORVault v2. Spec §7.7.
 * @dev UUPS-upgradeable, Timelock-admin. Funds-custody invariant: user funds are pulled
 *      into the vault at place-time; cancellation returns the exact pulled amount;
 *      execution swaps via vault push (never mints, never reroutes recipient).
 */
interface IPECOROrders {

    enum OrderType {
        LIMIT_BUY,
        LIMIT_SELL,
        STOP_LOSS,
        STOP_LIMIT_BUY,
        STOP_LIMIT_SELL
    }

    enum OrderStatus {
        PENDING,
        ACTIVATED,
        EXECUTED,
        CANCELLED,
        EXPIRED
    }

    /// @notice Trigger/limit prices are USD per whole token. minimumOutput is
    /// denominated in output-token base units and enforced on exact delivery.
    struct OrderRequest {
        OrderType orderType;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 triggerPrice;
        uint256 limitPrice;
        uint256 expiresAt;
        uint256 minimumOutput;
    }

    function placeOrder(OrderRequest calldata request) external returns (uint256 orderId);

    struct LimitOrder {
        uint256 id;
        address user;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 targetPrice;
        OrderType orderType;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
    }

    struct StopLimitOrder {
        uint256 id;
        address user;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 stopPrice;
        uint256 limitPrice;
        OrderType orderType;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
    }

    /**
     * @notice Initialize the UUPS proxy (spec §7.7)
     * @param priceOracle IPriceOracle address
     * @param vault IPECORVault v2 address (must grant OPERATOR_ROLE to this contract)
     * @param tracker ITransactionTracker address (may be zero at bootstrap)
     * @param admin Timelock — granted DEFAULT_ADMIN_ROLE
     */
    function initialize(
        address priceOracle,
        address vault,
        address tracker,
        address admin
    ) external;

    /// @notice Grant / revoke KEEPER_ROLE in one call (spec §7.7).
    function setKeeper(address keeper, bool authorized) external;

    function pause() external;

    function unpause() external;

    function placeLimitBuy(
        address stablecoin,
        address token,
        uint256 stablecoinAmount,
        uint256 targetPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeLimitSell(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 targetPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLoss(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 triggerPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLimitBuy(
        address stablecoin,
        address token,
        uint256 stablecoinAmount,
        uint256 stopPrice,
        uint256 limitPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLimitSell(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 stopPrice,
        uint256 limitPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function cancelLimitOrder(uint256 orderId) external;

    function cancelStopLimitOrder(uint256 orderId) external;

    function executeLimitOrder(uint256 orderId) external;

    function executeStopLimitOrder(uint256 orderId) external;

    function checkStopLimitActivation(uint256 orderId) external;

    function batchExecuteLimitOrders(
        uint256[] calldata orderIds
    ) external returns (uint256 executedCount);

    function batchCheckAndExecuteStopLimits(
        uint256[] calldata orderIds
    ) external returns (uint256 activatedCount, uint256 executedCount);

    function getLimitOrder(uint256 orderId) external view returns (LimitOrder memory);

    function getStopLimitOrder(uint256 orderId) external view returns (StopLimitOrder memory);

    function getUserLimitOrders(address user) external view returns (uint256[] memory);

    function getUserStopLimitOrders(address user) external view returns (uint256[] memory);

    function canExecuteLimitOrder(uint256 orderId) external view returns (bool, string memory);

    function getExecutableLimitOrders(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    function getActivatableStopLimits(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    function getExecutableStopLimits(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    event LimitOrderCreated(
        uint256 indexed orderId,
        address indexed user,
        OrderType orderType,
        uint256 amount,
        uint256 targetPrice
    );
    event LimitOrderExecuted(uint256 indexed orderId, uint256 executionPrice);
    event LimitOrderCancelled(uint256 indexed orderId);
    event StopLimitOrderCreated(
        uint256 indexed orderId,
        address indexed user,
        OrderType orderType,
        uint256 amount,
        uint256 stopPrice,
        uint256 limitPrice
    );
    event StopLimitActivated(uint256 indexed orderId, uint256 activationPrice);
    event StopLimitExecuted(uint256 indexed orderId, uint256 executionPrice);
    event StopLimitCancelled(uint256 indexed orderId);
    event KeeperUpdated(address indexed keeper, bool authorized);
}

